rowdata.pyStepsJavaSource:
StringBuffer csvbuff = new StringBuffer();

//Construct list of properties to be displayed on CSV
java.util.List propList = new ArrayList();
java.util.List propHeadersList = new ArrayList();
java.util.List<String> propTypes = null;
java.util.List<String> fieldModes = null;

if(tools.getParamValue("CSVPropertyTypes")!= null && !tools.getParamValue("CSVPropertyTypes").equals("")) {
  propTypes = java.util.Arrays.asList(tools.getParamValue("CSVPropertyTypes").split(","));
}

if(tools.getParamValue("CSVFieldModes")!= null && !tools.getParamValue("CSVFieldModes").equals("")) {
  fieldModes = java.util.Arrays.asList(tools.getParamValue("CSVFieldModes").split(",",-1));
}

Iterator iter = null;
String CSVProps = tools.getParamValue("CSVProperties");

String pageListProp = tools.getParamValue("PageListProperty");
ClipboardProperty resultsProp = myStepPage.getProperty(pageListProp);

if(!CSVProps.equals("")){
  propList = java.util.Arrays.asList(CSVProps.split(","));	
}else{
	ClipboardPage firstResultPage = resultsProp.getPageValue(1);
	java.util.Set propSet = firstResultPage.keySet();

	String propName="";

	iter = propSet.iterator();
	while (iter.hasNext()) {
		propName = (String)iter.next();
		if(propName.equals("pxObjClass")){
			continue;
		}
		propList.add(propName);	
	}
}

//form property-alias map for aggregate fields
ClipboardProperty fieldMapping = myStepPage.getProperty("pyMapping");
String fieldName;
java.util.Map<String, String> fieldMap = new java.util.HashMap<>();
ClipboardPage fieldPg;
for(int i = 1; i <= fieldMapping.size(); i++) {
  fieldPg = fieldMapping.getPageValue(i);
  fieldName = fieldPg.getString("pyColumnName");
  if (fieldName.indexOf(".") != -1) {
    fieldMap.put(fieldName, fieldPg.getString("pyPropertyName"));  
  }
}

String propertyName;
String aliasName;
String joinedClassName;
ClipboardPage fieldPage;
java.util.Map<String, String> columnAliasMap = new java.util.HashMap<>();
ClipboardProperty uiFields = myStepPage.getProperty(".pyReportDefinition.pyUI.pyBody.pyUIFields");

Iterator it = uiFields.iterator();

while (it.hasNext()) {
	fieldPage = ((ClipboardProperty)it.next()).getPageValue();
  fieldName = fieldPage.getString(".pyFieldName");
  if (fieldPage.getString("pyFunction") != "") {
    aliasName = fieldMap.get(fieldName);
    if (fieldName.indexOf(".") != -1) {
      if (fieldName.indexOf(".") != 0) {
        joinedClassName = (fieldName.split("\\."))[0];
      	propertyName = (fieldName.split("\\."))[1];
      	fieldName = ".pxPages("+joinedClassName+")."+propertyName;
      } else {
        fieldName = (fieldName.split("\\."))[1];
      }
    columnAliasMap.put(fieldName, aliasName);
    }
  }
}

//populating decimalPrecisionMap
java.util.Map <String, Integer> decimalPrecisionMap = new java.util.HashMap<>(); 
int k = 0;
String propName="";
String propType="";
String className = myStepPage.getString("pyObjClass");
if (propTypes != null) {
  iter = propTypes.iterator();
  while (iter.hasNext()) {
    propType = (String)iter.next();
    if ("Decimal".equals(propType)) {
      propName = (String)propList.get(k);
      if (columnAliasMap.containsKey(propName)) {
        propName = (String)columnAliasMap.get(propName);
      }
      String decimalPrecision = tools.getThread().getDictionary().getQualifier(className,propName,"pyDecimalPrecision");
	    if(!StringUtils.isBlank(decimalPrecision)) {
		    decimalPrecisionMap.put(propName, Integer.valueOf(decimalPrecision));
      } else {
		    decimalPrecisionMap.put(propName, -1);
      }
    }
    k++;
  }
}


//loop through properties and add as column headers in the CSV file
String CSVPropHeaders = tools.getParamValue("CSVPropHeaders");
java.util.Map headersMap = null;
Object hmObj = tools.getParameterPage().getObject("HeadersMap");
if(hmObj instanceof java.util.Map) {
   headersMap = (java.util.Map)hmObj;
}
  if(CSVPropHeaders!= null && !"".equals(CSVPropHeaders)){
    propHeadersList = java.util.Arrays.asList(CSVPropHeaders.split(","));
    iter = propHeadersList.iterator();
  } else if (headersMap !=null && headersMap.size()>0){
        StringBuffer headersBuffer = new StringBuffer();
		Iterator<String> headersIter = propList.iterator();
    	if(headersIter.hasNext()){
		while(headersIter.hasNext()){
				headersBuffer.append(headersMap.get(headersIter.next()));
				headersBuffer.append(",");
		}
   iter = java.util.Arrays.asList(headersBuffer.substring(0, headersBuffer.length()-1).split(",")).iterator();
        }
    else{
      iter = propList.iterator();
    }
  }else {
    iter = propList.iterator();
  }

int z = 0;
while(iter.hasNext()){
	if(fieldModes!=null && fieldModes.get(z)!=null && (fieldModes.get(z).equals("Calculated") || fieldModes.get(z).equals("Read Only"))){
		csvbuff.append(((String)iter.next()) + "(read-only)");
	}
	else{
		csvbuff.append((String)iter.next());
	}

	if(iter.hasNext()){
		csvbuff.append(listSeperator);
	}
	z++;
}


csvbuff.append("\n");

ClipboardPage propPage =null;
String propValue = "";
int j=0;
for(int i =1; i<=resultsProp.size(); i++){
	iter = propList.iterator();
	propPage = resultsProp.getPageValue(i);
	while(iter.hasNext()){

		propName = (String)iter.next();
    if (columnAliasMap.containsKey(propName)) {
      propName = (String)columnAliasMap.get(propName);
    }
		propValue = propPage.getString(propName);

	  //get default date formats for excel for the requestor locale
		PublicAPI tools = null;
		PRThread  mThread = (PRThread)ThreadContainer.get();
		if (mThread != null) {
			tools = mThread.getPublicAPI();
		}

      String EXCEL_DATE_TIME_DEFAULT_FORMAT = "M/d/yyyy H:mm";
	  String EXCEL_DATE_DEFAULT_FORMAT = "M/d/yyyy";

      ClipboardPage defaultDateFormatsForExcelClipboardPage = tools.createPage("PegaAccel-DataImport", "defaultDateFormatsForExcelPage");      
  	  defaultDateFormatsForExcelClipboardPage.putString(".pyLocale", localeCode);
		ParameterPage newParamsPage = new ParameterPage();

		StringMap params = new HashStringMap();
		params.putString("pxObjClass", "Rule-Declare-DecisionTable");
		params.putString("pyClassName", "PegaAccel-DataImport");
		params.putString("pyPurpose", "pzExcelDefaultDateTimeFormat");
		tools.doAction(params, defaultDateFormatsForExcelClipboardPage, newParamsPage);   

        String dateFormat  = defaultDateFormatsForExcelClipboardPage.getString("pyExcelDefaultDateFormat");
		if(StringUtils.isBlank(dateFormat)){
			dateFormat = EXCEL_DATE_DEFAULT_FORMAT;
		}
		dateFormat = dateFormat.replaceAll("\"", "");
		String dateTimeFormat = defaultDateFormatsForExcelClipboardPage.getString("pyExcelDefaultDateTimeFormat");		
		if(StringUtils.isBlank(dateTimeFormat)){
			dateTimeFormat = EXCEL_DATE_TIME_DEFAULT_FORMAT;
		}
		dateTimeFormat = dateTimeFormat.replaceAll("\"", "");

          if(!propValue.equals("") && propTypes != null){
            propType = propTypes.get(j); 
            if ((propType.equals("Decimal"))) {
              propValue = PRNumberFormat.format(localeCode, PRNumberFormat.DEFAULT_DECIMAL, false, null, decimalPrecisionMap.get(propName), new BigDecimal(propValue));
            } else if (propType.equals("Double")) {
              propValue = PRNumberFormat.format(localeCode,PRNumberFormat.DEFAULT_DECIMAL, false, null,  Double.parseDouble(propValue));
            } else if ("Date".equals(propType)) {
				String userTimeZone = mThread.getTimeZoneName();		
				Date date = PRDateFormat.parseAsDate(localeCode, userTimeZone, null, propValue);
			  	java.text.DateFormat sdf = new java.text.SimpleDateFormat(dateFormat, com.pega.apache.commons.lang.LocaleUtils.toLocale(localeCode));
				sdf.setLenient(false);
				sdf.setTimeZone(java.util.TimeZone.getTimeZone(userTimeZone));
				propValue = sdf.format(date);			
            } else if ("DateTime".equals(propType) || "Date Time".equals(propType)) {
				String userTimeZone = mThread.getTimeZoneName();
				DateTimeUtils dtu = pega.getDateTimeUtils();
				propValue = dtu.formatDateTime(propValue, dateTimeFormat, userTimeZone, localeCode);			
            }
          }
      if(propValue.contains("\"")){
          propValue = propValue.replaceAll("\"", "\"\"");
        }

        if(propValue.contains(listSeperator) || propValue.contains("\"") || propValue.contains("\n") ||  propValue.contains("\r\n") ||  propValue.contains("\r")){
		    csvbuff.append("\""+propValue+"\"");
		} else {
            csvbuff.append(propValue);  
        }



		if(iter.hasNext()){
			csvbuff.append(listSeperator);
		}
      j++;
	}
  j=0;
	csvbuff.append("\n");
}

CSVString = csvbuff.toString();

char sep = PRFile.separatorChar;
String exportPath= tools.getProperty("pxProcess.pxServiceExportPath").getStringValue();
DateTimeUtils dtu = ThreadContainer.get().getDateTimeUtils();

String fileNameParam = tools.getParamValue("FileName");
if(fileNameParam.equals("")){
	fileNameParam = "RecordsToCSV";
}
Boolean appendTimeStamp = tools.getParamAsBoolean(ImmutablePropertyInfo.TYPE_TRUEFALSE,"AppendTimeStampToFileName");

FileName+=fileNameParam;
if(appendTimeStamp){
	FileName+="_";
	FileName+=dtu.getCurrentTimeStamp();
}
FileName+=".csv";
String strSQLfullPath = exportPath+ sep + FileName;
PRFile f = new PRFile(strSQLfullPath);
try{
 // Create file 
 PROutputStream stream = new PROutputStream(f);
 PRWriter out = new PRWriter(stream, null, false);
 // Bug with Excel reading a file starting with 'ID' as SYLK file. If CSV starts with ID, prepend an empty space.
 if(CSVString.startsWith("ID")){
	CSVString=" "+CSVString;
 }
 out.write(CSVString);
 //Close the output stream
 out.close();
}catch (Exception e) {
 oLog.error("Error writing csv file: " + e.getMessage());
}
